// Gerendertes Häuschen von außen (Blender/Cycles) in Tiefen-Ebenen + scharfe Nahaufnahmen fürs Hineinzoomen
const AUSSEN = (() => { const d = {"fern": "data:image/webp;base64,", "mitte": "data:image/webp;base64,", "haus": "data:image/webp;base64,", "busch": "data:image/webp;base64,", "blatt": "data:image/webp;base64,", "mittel": "data:image/webp;base64,", "nah": "data:image/webp;base64,", "pkt": {"lichterkette": [[395.0, 324.0, [1, 0.62, 0.22]], [415.625, 332.419035512032, [1, 0.32, 0.3]], [436.25, 339.55634918610406, [0.5, 1, 0.35]], [456.875, 344.3253497152483, [1, 0.62, 0.22]], [477.5, 346.0, [1, 0.32, 0.3]], [498.125, 344.3253497152483, [0.5, 1, 0.35]], [518.75, 339.55634918610406, [1, 0.62, 0.22]], [539.375, 332.419035512032, [1, 0.32, 0.3]], [560.0, 324.0, [0.5, 1, 0.35]]], "laterne": [662.3, 501.9], "fenster": [[705, 372, 38], [555, 405, 17], [735, 505, 19]], "rauch": [765.0, 231.5]}, "r_mittel": [505, 257, 905, 487], "r_nah": [630, 327, 780, 417]};
  const Z = {bereit: false, pkt: d.pkt, r_mittel: d.r_mittel, r_nah: d.r_nah}; let n = 0, fertig; const namen = ['fern', 'mitte', 'haus', 'busch', 'blatt', 'mittel', 'nah'];
  Z.geladen = new Promise(r => fertig = r);
  for(const k of namen){ const im = new Image(); im.onload = () => { if(++n === namen.length){ Z.bereit = true; fertig(); } }; im.src = d[k]; Z[k] = im; }
  return Z; })();
